import random

def generate_password(length=12):
    password = ''
    for i in range(length):
        char_type = random.choice(['letter', 'digit', 'symbol'])
        if char_type == 'letter':
            char = random.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
        elif char_type == 'digit':
            char = random.choice('0123456789')
        else:
            char = random.choice('!@#$%^&*()')
        password += char

    return password

print(generate_password())

