import random

def get_lottery_numbers():
    numbers = []
    while len(numbers) < 5:
        num = random.randint(1, 99)
        if num not in numbers:
            numbers.append(num)
    return numbers

if __name__ == "__main__":
    winning_numbers = get_lottery_numbers()
    print(f"The winning numbers are {winning_numbers}")

    your_numbers = [23, 47, 61, 70, 89]
    if set(your_numbers) & set(winning_numbers):
        print("Congratulations! You won!")
    else:
        print("Better luck next time!")

import yfinance as yf
import datetime

class Backtest:
    def __init__(self, symbol):
        self.symbol = symbol

    def download_data(self):
        start = "2018-01-01"
        end = datetime.datetime.now().strftime("%Y-%m-%d")
        self.prices = yf.download(self.symbol, start=start, end=end)['Adj Close']

    def run_strategy(self):
        for date, price in self.prices.iteritems():
            self.position = self.symbol
            self.position_price = price
            break

if __name__ == "__main__":
    bt = Backtest("GOOG")
    bt.download_data()
    bt.run_strategy()

