def guest_list(guests):
    if len(guests) > 10:
        print("Too many guests!")
        return

    for i, person in enumerate(guests):
        if " " not in person:
            print(f"Guest {i+1}: {person}")
        elif "Dr." in person:
            title_end = person.rfind(" ")
            name = person[title_end+1:]
            print(f"Dr. {name} ({person[:title_end]})")
        else:
            name_end = person.find(" ")
            name = person[name_end+1:] + ", " + person[:name_end]
            print(f"{name}")

